import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, mix, mul, add } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text'; // unused but allowed import list
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives'; // primitives may be empty

/** @typedef {import('three').Object3D} Object3D */
/** @typedef {{ imageUrl: string, depthMapUrl?: string, meshUrl?: string, textContent?: any[], cinematicPrimitives?: any[], intent?: any, intent?: any, intent?: any }} NodeConfig */
/** @typedef {{ THREE: any, textureLoader: any, glbLoader: any, videoLoader?: any, fontAtlas: any, primitives: any, emit: any, tier?: string }} NodeContext */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container – the adapter will position/rotate/scale it.
  const root = new Group();

  // -----------------------------------------------------------------------
  // Geometry – size matches the atlas region aspect ratio (width / height)
  // -----------------------------------------------------------------------
  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlasRect.w / atlasRect.h;
  const planeGeom = new PlaneGeometry(aspect, 1, 1, 1); // height 1 unit, width = aspect

  // -----------------------------------------------------------------------
  // Material – MeshBasicNodeMaterial with texture node
  // -----------------------------------------------------------------------
  const material = new MeshBasicNodeMaterial();

  /** @type {import('three').Texture | null} */
  let textureResource = null;

  // Load texture asynchronously but keep function synchronous.
  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      textureResource = tex;
      // Apply the texture to the material using a texture node.
      material.map = texture(tex);
      material.needsUpdate = true;
    })
    .catch(() => {
      // Silently ignore loading errors – plane will remain untextured.
    });

  // -----------------------------------------------------------------------
  // Mesh – combine geometry and material
  // -----------------------------------------------------------------------
  const plane = new Mesh(planeGeom, material);
  plane.frustumCulled = false; // ensure visibility even if off‑center
  root.add(plane);

  // -----------------------------------------------------------------------
  // Billboard – always face the camera
  // -----------------------------------------------------------------------
  plane.onBeforeRender = function (_renderer, _scene, camera) {
    // Align plane normal to camera direction
    const pos = plane.position.clone();
    plane.lookAt(camera.position);
    plane.position.copy(pos);
  };

  // -----------------------------------------------------------------------
  // Apply cinematic primitives declared in the config (none in this spec)
  // -----------------------------------------------------------------------
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (typeof ctx.primitives[prim.name] === 'function') {
        const instance = ctx.primitives[prim.name](root, prim.params);
        primitiveInstances.push(instance);
      }
    }
  }

  // -----------------------------------------------------------------------
  // User data – cleanup and empty handlers
  // -----------------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = function () {
    // Dispose geometry and material
    planeGeom.dispose();
    material.dispose();

    // Dispose texture if it was loaded
    if (textureResource) {
      textureResource.dispose();
    }

    // Kill any primitive resources
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }

    // Kill any GSAP timelines (none in this node, but defensive)
    gsap.globalTimeline.clear();
  };

  return root;
}
